            "id": "govkit:AddressInput",
            "kind": "component",
            "import": {
                "package": "@aragon/gov-ui-kit",
                "name": "AddressInput"
            },
            "description": "Text input that resolves wallet or contract addresses and ENS names.",
            "useWhen": [
                "Capturing a wallet/contract address or ENS name in a form",
                "Flows needing checksummed address + normalized ENS output"
            ],
            "alternatives": [
                {
                    "id": "govkit:AddressOutput",
                    "useWhen": "Use AddressOutput for read-only address display."
                },
                {
                    "id": "govkit:InputText",
                    "useWhen": "Use InputText for plain text without address/ENS resolution."
                }
            ],
            "keyProps": [
                {
                    "name": "value",
                    "contract": "Controlled current input text for an address or ENS name; defaults to an empty string."
                },
                {
                    "name": "onChange",
                    "contract": "Receives edited input text; with enforceChecksum enabled, valid or all-uppercase addresses are normalized to checksum form, and surrounding whitespace is trimmed on blur. Clearing emits undefined."
                },
                {
                    "name": "onAccept",
                    "contract": "After debounce and ENS/address resolution, receives { address, name } with a checksum address and normalized ENS name, or undefined when input is invalid or fails checksum enforcement."
                },
                {
                    "name": "chainId",
                    "contract": "Selects the block-explorer network; ENS resolution remains on mainnet."
                },
                {
                    "name": "enforceChecksum",
                    "contract": "Defaults true; rejects mixed-case addresses that fail strict EIP-55 validation while accepted output remains checksum formatted."
                },
                {
                    "name": "hideControls",
                    "contract": "Hides ENS/address toggle, block-explorer link, copy, clear and paste controls."
                }
            ],
            "constraints": [
                "Uses wagmi hooks and useQueryClient, so it must render under Wagmi and React-Query providers (GukModulesProvider supplies these)",
                "onChange represents edited input state and may normalize a valid address to checksum form or trim surrounding whitespace on blur; it is separate from accepted output",
                "onAccept is debounced by 300ms and emits a resolved checksum address plus normalized ENS name, or undefined for invalid input/checksum errors",
                "chainId selects the explorer network while ENS resolution always uses mainnet"
            ],
            "composition": [
                "Wraps InputContainer and renders MemberAvatar plus optional ENS/address toggle, explorer, copy, clear and paste controls.",
                "App AddressesInputItem keeps local raw text state and writes accepted {address,name} into form state for duplicate/custom validation."
            ],
            "references": {
                "source": "kit:src/modules/components/addressInput/addressInput.tsx:67",
